package br.com.inframonitor.security;
import br.com.inframonitor.common.api.ErroResposta; import tools.jackson.databind.ObjectMapper; import jakarta.servlet.http.*; import org.springframework.http.MediaType; import org.springframework.security.core.AuthenticationException; import org.springframework.security.web.AuthenticationEntryPoint; import org.springframework.stereotype.Component; import java.io.IOException;
@Component public class ApiAuthenticationEntryPoint implements AuthenticationEntryPoint { private final ObjectMapper mapper; public ApiAuthenticationEntryPoint(ObjectMapper mapper){this.mapper=mapper;} public void commence(HttpServletRequest r,HttpServletResponse s,AuthenticationException e)throws IOException{ escrever(r,s,401,"Unauthorized","UNAUTHORIZED","Autenticacao obrigatoria"); } void escrever(HttpServletRequest r,HttpServletResponse s,int status,String error,String code,String message)throws IOException{s.setStatus(status);s.setContentType(MediaType.APPLICATION_JSON_VALUE);mapper.writeValue(s.getOutputStream(), ErroResposta.de(status,error,code,message,r.getRequestURI()));} }
